import { unstable_noStore as noStore } from 'next/cache';

export default function Home() {
  // Mark this route as dynamic to ensure it's not cached
  noStore();

  // Log page view to analytics service (non-blocking)
  logPageView();

  return (
    <main>
      <h1>Welcome to our website!</h1>
      <p>We're glad you're here. Your visit has been logged for analytics purposes.</p>
    </main>
  );
}

async function logPageView() {
  'use server';

  // This function will be called but won't block the response
  // Next.js will handle this as post-response work
  try {
    // Simulate analytics service call
    console.log('Logging page view to analytics service...');

    // In a real implementation, you would call your analytics service here
    // For example: await analyticsService.logPageView();

  } catch (error) {
    console.error('Failed to log page view:', error);
  }
}

